(()=>{const reduce=matchMedia('(prefers-reduced-motion:reduce)'),played=new WeakSet(),active=new Set();const animate=(el,frames,options)=>{if(reduce.matches)return;const a=el.animate(frames,options);active.add(a);a.finished.finally(()=>active.delete(a)).catch(()=>{})};const reveal=new IntersectionObserver(entries=>{for(const e of entries){if(!e.isIntersecting||played.has(e.target))continue;played.add(e.target);animate(e.target,[{opacity:.4,transform:'translate3d(0,18px,0)'},{opacity:1,transform:'none'}],{duration:450,easing:'cubic-bezier(.23,1,.32,1)'});reveal.unobserve(e.target)}},{threshold:.12});document.querySelectorAll('.esc-event-copy,.esc-event-art,.original-sponsors>h2,.esc-event-preview>h2').forEach(el=>reveal.observe(el));const lantern=document.querySelector('.festival-lantern');if(lantern)new IntersectionObserver(entries=>{lantern.classList.toggle('lantern-visible',entries[0].isIntersecting&&!document.hidden&&!reduce.matches)}).observe(document.querySelector('#esc-about'));window.addEventListener('urvion:intro-dismissed',()=>{const date=document.querySelector('.voyage-date');if(date)animate(date,[{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'none'}],{duration:600,delay:450,easing:'cubic-bezier(.23,1,.32,1)',fill:'backwards'})});reduce.addEventListener('change',()=>{if(reduce.matches){active.forEach(a=>a.cancel());lantern?.classList.remove('lantern-visible')}});document.addEventListener('visibilitychange',()=>{if(document.hidden){active.forEach(a=>a.finish());lantern?.classList.remove('lantern-visible')}})})();
